DELIMITER $$
--
-- Procedimientos
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_poblar_cliente` (IN `p_hasta` INT)   BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE n INT;
    DECLARE nom VARCHAR(80);
    DECLARE ape VARCHAR(80);
    DECLARE mail_base VARCHAR(120);
    DECLARE tel VARCHAR(20);
    DECLARE mail VARCHAR(120);
    DECLARE fecha DATE;

    -- Ciclo de 48 nombres/apellidos (igual que tus 48 primeros registros)
    SET n = 48;

    WHILE i <= p_hasta DO
        SET nom = ELT(((i-1) MOD n)+1,
            'Juan','María','Carlos','Ana','Luis','Laura','Pedro','Sofía',
            'Diego','Valentina','Andrés','Camila','Jorge','Daniela','Felipe','Isabella',
            'Sebastián','Mariana','Ricardo','Paula','Fernando','Natalia','Mauricio','Carolina',
            'Alejandro','Gabriela','Óscar','Juliana','Santiago','Manuela','Julián','Catalina',
            'Mateo','Luciana','Emilio','Antonia','Samuel','Martina','Tomás','Salomé',
            'Simón','Elena','Miguel','Violeta','Daniel','Renata','Nicolás','Amelia');

        SET ape = ELT(((i-1) MOD n)+1,
            'Pérez','Gómez','Rodríguez','Martínez','García','López','Sánchez','Ramírez',
            'Torres','Flores','Rivera','Castro','Ortiz','Moreno','Jiménez','Rojas',
            'Vargas','Herrera','Medina','Aguilar','Vega','Cruz','Mendoza','Silva',
            'Ríos','Peña','Navarro','Cortés','Salazar','Suárez','Restrepo','Guzmán',
            'Barrera','Bermúdez','Quintero','Cárdenas','Acosta','Delgado','Benavides','Zapata',
            'Arango','Vélez','Hoyos','Londoño','Ospina','Giraldo','Uribe','Betancur');

        -- Email sin tildes (reemplazos básicos)
        SET mail_base = LOWER(CONCAT(nom,'.',ape));
        SET mail_base = REPLACE(mail_base,'á','a');
        SET mail_base = REPLACE(mail_base,'é','e');
        SET mail_base = REPLACE(mail_base,'í','i');
        SET mail_base = REPLACE(mail_base,'ó','o');
        SET mail_base = REPLACE(mail_base,'ú','u');
        SET mail_base = REPLACE(mail_base,'ñ','n');

        SET tel  = CONCAT('3001110', LPAD(i,3,'0'));
        SET mail = CONCAT(mail_base, i, '@mail.com');
        SET fecha = DATE_ADD('2024-01-05', INTERVAL (i-1)*2 DAY);

        -- Evita duplicados si ya existe ese email
        IF NOT EXISTS (SELECT 1 FROM cliente WHERE Email = mail) THEN
            VALUES (nom, ape, tel, mail, fecha);
        END IF;

        SET i = i + 1;
    END WHILE;
END$$

DELIMITER ;

