--
-- Estructura para la vista `consulta_02_servicios_mas_solicitados`
--
DROP TABLE IF EXISTS `consulta_02_servicios_mas_solicitados`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `consulta_02_servicios_mas_solicitados`  AS SELECT `s`.`Nombre_servicio` AS `Nombre_servicio`, count(0) AS `veces_solicitado` FROM (`servicio_cita` `sc` join `servicio` `s` on(`s`.`ID_Servicio` = `sc`.`FK_Servicio`)) GROUP BY `s`.`ID_Servicio`, `s`.`Nombre_servicio` ORDER BY count(0) DESC ;

