--
-- Estructura para la vista `consulta_03_ingresos_por_metodo_pago`
--
DROP TABLE IF EXISTS `consulta_03_ingresos_por_metodo_pago`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `consulta_03_ingresos_por_metodo_pago`  AS SELECT `pago`.`MetodoPago` AS `MetodoPago`, count(0) AS `num_pagos`, sum(`pago`.`MontoTotal`) AS `total_recaudado` FROM `pago` GROUP BY `pago`.`MetodoPago` ORDER BY sum(`pago`.`MontoTotal`) DESC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `consulta_04_ingresos_por_mes`
