DROP TABLE IF EXISTS `consulta_04_ingresos_por_mes`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `consulta_04_ingresos_por_mes`  AS SELECT date_format(`pago`.`FechaHoraPago`,'%Y-%m') AS `mes`, count(0) AS `num_pagos`, sum(`pago`.`MontoTotal`) AS `ingresos` FROM `pago` GROUP BY date_format(`pago`.`FechaHoraPago`,'%Y-%m') ORDER BY date_format(`pago`.`FechaHoraPago`,'%Y-%m') ASC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `consulta_05_ingresos_por_barbero`
--
DROP TABLE IF EXISTS `consulta_05_ingresos_por_barbero`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `consulta_05_ingresos_por_barbero`  AS SELECT `b`.`Nombre` AS `barbero`, count(`p`.`ID_Pago`) AS `pagos`, sum(`p`.`MontoTotal`) AS `ingresos` FROM (((`barbero` `b` join `cita` `c` on(`c`.`FK_ID_Barbero` = `b`.`ID_Barbero`)) join `pago_cita` `pc` on(`pc`.`FK_ID_Cita` = `c`.`ID_Cita`)) join `pago` `p` on(`p`.`ID_Pago` = `pc`.`FK_ID_Pago`)) GROUP BY `b`.`ID_Barbero`, `b`.`Nombre` ORDER BY sum(`p`.`MontoTotal`) DESC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `consulta_06_top10_clientes_mas_citas`
--
DROP TABLE IF EXISTS `consulta_06_top10_clientes_mas_citas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `consulta_06_top10_clientes_mas_citas`  AS SELECT `cl`.`ID_Cliente` AS `ID_Cliente`, concat(`cl`.`Nombre`,' ',`cl`.`Apellido`) AS `cliente`, count(0) AS `citas_completadas` FROM (`cliente` `cl` join `cita` `c` on(`c`.`FK_ID_Cliente` = `cl`.`ID_Cliente`)) WHERE `c`.`Estado` = 'Completada' GROUP BY `cl`.`ID_Cliente`, `cl`.`Nombre`, `cl`.`Apellido` ORDER BY count(0) DESC LIMIT 0, 10 ;

-- --------------------------------------------------------

--
-- Estructura para la vista `consulta_07_top10_clientes_mas_gastan`
--
DROP TABLE IF EXISTS `consulta_07_top10_clientes_mas_gastan`;

