CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `consulta_08_clientes_sin_citas`  AS SELECT `cl`.`ID_Cliente` AS `ID_Cliente`, `cl`.`Nombre` AS `Nombre`, `cl`.`Apellido` AS `Apellido`, `cl`.`Email` AS `Email` FROM (`cliente` `cl` left join `cita` `c` on(`c`.`FK_ID_Cliente` = `cl`.`ID_Cliente`)) WHERE `c`.`ID_Cita` is null ;

