--
-- Estructura para la vista `consulta_09_citas_barbero_estado`
--
DROP TABLE IF EXISTS `consulta_09_citas_barbero_estado`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `consulta_09_citas_barbero_estado`  AS SELECT `b`.`Nombre` AS `barbero`, sum(`c`.`Estado` = 'Completada') AS `completadas`, sum(`c`.`Estado` = 'Cancelada') AS `canceladas`, sum(`c`.`Estado` = 'No asistió') AS `no_asistio`, sum(`c`.`Estado` = 'Confirmada') AS `confirmadas`, sum(`c`.`Estado` = 'Pendiente') AS `pendientes` FROM (`barbero` `b` join `cita` `c` on(`c`.`FK_ID_Barbero` = `b`.`ID_Barbero`)) GROUP BY `b`.`ID_Barbero`, `b`.`Nombre` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `consulta_10_pct_cancelacion_barbero`
--
DROP TABLE IF EXISTS `consulta_10_pct_cancelacion_barbero`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `consulta_10_pct_cancelacion_barbero`  AS SELECT `b`.`Nombre` AS `barbero`, count(0) AS `total_citas`, sum(`c`.`Estado` = 'Cancelada') AS `canceladas`, round(100 * sum(`c`.`Estado` = 'Cancelada') / count(0),2) AS `pct_cancelacion` FROM (`barbero` `b` join `cita` `c` on(`c`.`FK_ID_Barbero` = `b`.`ID_Barbero`)) GROUP BY `b`.`ID_Barbero`, `b`.`Nombre` ORDER BY round(100 * sum(`c`.`Estado` = 'Cancelada') / count(0),2) DESC ;

-- --------------------------------------------------------

