-- --------------------------------------------------------

--
-- Estructura para la vista `consulta_12_ticket_por_servicio`
--
DROP TABLE IF EXISTS `consulta_12_ticket_por_servicio`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `consulta_12_ticket_por_servicio`  AS SELECT `s`.`Nombre_servicio` AS `Nombre_servicio`, count(0) AS `pagos`, round(avg(`p`.`MontoTotal`),2) AS `ticket_promedio`, min(`p`.`MontoTotal`) AS `minimo`, max(`p`.`MontoTotal`) AS `maximo` FROM (((`servicio` `s` join `cita` `c` on(`c`.`Servicio` = `s`.`Nombre_servicio`)) join `pago_cita` `pc` on(`pc`.`FK_ID_Cita` = `c`.`ID_Cita`)) join `pago` `p` on(`p`.`ID_Pago` = `pc`.`FK_ID_Pago`)) GROUP BY `s`.`ID_Servicio`, `s`.`Nombre_servicio` ORDER BY round(avg(`p`.`MontoTotal`),2) DESC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `consulta_13_agenda_proximos_7_dias`
--
DROP TABLE IF EXISTS `consulta_13_agenda_proximos_7_dias`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `consulta_13_agenda_proximos_7_dias`  AS SELECT `c`.`FechaHoraCita` AS `FechaHoraCita`, concat(`cl`.`Nombre`,' ',`cl`.`Apellido`) AS `cliente`, `b`.`Nombre` AS `barbero`, `c`.`Servicio` AS `Servicio`, `c`.`Estado` AS `Estado` FROM ((`cita` `c` join `cliente` `cl` on(`cl`.`ID_Cliente` = `c`.`FK_ID_Cliente`)) join `barbero` `b` on(`b`.`ID_Barbero` = `c`.`FK_ID_Barbero`)) WHERE `c`.`Estado` in ('Confirmada','Pendiente') AND `c`.`FechaHoraCita` >= '2026-10-29' AND `c`.`FechaHoraCita` < '2026-10-29' + interval 7 day ORDER BY `c`.`FechaHoraCita` ASC, `b`.`Nombre` ASC ;

