--
-- Estructura para la vista `consulta_14_clientes_sobre_promedio`
--
DROP TABLE IF EXISTS `consulta_14_clientes_sobre_promedio`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `consulta_14_clientes_sobre_promedio`  AS SELECT `cl`.`ID_Cliente` AS `ID_Cliente`, concat(`cl`.`Nombre`,' ',`cl`.`Apellido`) AS `cliente`, count(0) AS `total_citas` FROM (`cliente` `cl` join `cita` `c` on(`c`.`FK_ID_Cliente` = `cl`.`ID_Cliente`)) GROUP BY `cl`.`ID_Cliente`, `cl`.`Nombre`, `cl`.`Apellido` HAVING count(0) > (select avg(`x`.`n`) from (select count(0) AS `n` from `cita` group by `cita`.`FK_ID_Cliente`) `x`) ORDER BY count(0) DESC LIMIT 0, 20 ;

